select payload from `history-rfq-record`
where bu_id=#{buId} and payload->>'$.documentId'=#{id}
order by id,version for update

select id,payload from history_document
where bu_id=#{bu} and ((project_id is null and scope='BU共享') or (project_id=#{project} and scope='仅当前项目'))
    and id in #{id}
